CREATE TABLE IF NOT EXISTS administradores (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,nome VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,senha_hash VARCHAR(255) NOT NULL,criado_em TIMESTAMP DEFAULT CURRENT_TIMESTAMP,atualizado_em TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS categorias (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,nome VARCHAR(120) NOT NULL,slug VARCHAR(120) NOT NULL UNIQUE,ordem INT UNSIGNED NOT NULL DEFAULT 0,ativo BOOLEAN NOT NULL DEFAULT 1,criado_em TIMESTAMP DEFAULT CURRENT_TIMESTAMP,atualizado_em TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS produtos (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,categoria_id INT UNSIGNED NOT NULL,nome VARCHAR(160) NOT NULL,descricao TEXT NOT NULL,preco DECIMAL(10,2) NOT NULL CHECK(preco>=0),imagem_url VARCHAR(2048) NOT NULL,imagem_alt VARCHAR(255) NOT NULL,destaque BOOLEAN NOT NULL DEFAULT 0,selo VARCHAR(80),ordem INT UNSIGNED DEFAULT 0,ordem_destaque INT UNSIGNED DEFAULT 0,ativo BOOLEAN NOT NULL DEFAULT 1,criado_em TIMESTAMP DEFAULT CURRENT_TIMESTAMP,atualizado_em TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(categoria_id) REFERENCES categorias(id) ON DELETE RESTRICT);
CREATE TABLE IF NOT EXISTS secoes (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,chave VARCHAR(80) NOT NULL UNIQUE,subtitulo VARCHAR(255) NOT NULL DEFAULT '',titulo VARCHAR(255) NOT NULL,descricao TEXT NOT NULL,imagem_url VARCHAR(2048),imagem_alt VARCHAR(255),botao_texto VARCHAR(120),botao_url VARCHAR(2048),atualizado_em TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS fotos (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,grupo ENUM('galeria','instagram') NOT NULL,imagem_url VARCHAR(2048) NOT NULL,texto_alternativo VARCHAR(255) NOT NULL,legenda VARCHAR(255),link_url VARCHAR(2048),ordem INT UNSIGNED DEFAULT 0,ativo BOOLEAN NOT NULL DEFAULT 1,criado_em TIMESTAMP DEFAULT CURRENT_TIMESTAMP,atualizado_em TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS avaliacoes (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,nome_cliente VARCHAR(120) NOT NULL,nota TINYINT NOT NULL CHECK(nota BETWEEN 1 AND 5),comentario VARCHAR(1500) NOT NULL,status ENUM('pendente','aprovada','rejeitada') NOT NULL DEFAULT 'pendente',criado_em TIMESTAMP DEFAULT CURRENT_TIMESTAMP,moderado_em DATETIME,moderado_por INT UNSIGNED,FOREIGN KEY(moderado_por) REFERENCES administradores(id) ON DELETE SET NULL,INDEX(status,criado_em));
CREATE TABLE IF NOT EXISTS estabelecimento (id INT UNSIGNED PRIMARY KEY CHECK(id=1),nome VARCHAR(160) NOT NULL,descricao TEXT NOT NULL,telefone VARCHAR(30) NOT NULL,whatsapp VARCHAR(30) NOT NULL,email VARCHAR(190),endereco VARCHAR(255) NOT NULL,numero VARCHAR(20) NOT NULL,complemento VARCHAR(120),bairro VARCHAR(120) NOT NULL,cidade VARCHAR(120) NOT NULL,estado CHAR(2) NOT NULL,cep VARCHAR(10) NOT NULL,maps_url VARCHAR(2048) NOT NULL,maps_embed_url VARCHAR(2048) NOT NULL,instagram_url VARCHAR(2048) NOT NULL,facebook_url VARCHAR(2048),logo_url VARCHAR(2048) NOT NULL,atualizado_em TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS horarios_funcionamento (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,dia_semana TINYINT NOT NULL UNIQUE CHECK(dia_semana BETWEEN 0 AND 6),fechado BOOLEAN NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS intervalos_funcionamento (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,horario_id INT UNSIGNED NOT NULL,abertura TIME NOT NULL,fechamento TIME NOT NULL,encerra_no_dia_seguinte BOOLEAN NOT NULL DEFAULT 0,FOREIGN KEY(horario_id) REFERENCES horarios_funcionamento(id) ON DELETE CASCADE,CHECK(encerra_no_dia_seguinte=1 OR fechamento>abertura));
CREATE TABLE IF NOT EXISTS sessoes (token_hash CHAR(64) PRIMARY KEY,administrador_id INT UNSIGNED NOT NULL,expira_em DATETIME NOT NULL,FOREIGN KEY(administrador_id) REFERENCES administradores(id) ON DELETE CASCADE,INDEX(expira_em));
